<template><div class="app"><aside class="sidebar"><div class="brand"><img src="/infravault-logo.svg" alt="" class="brand-logo"> <span>InfraVault</span></div><NuxtLink class="nav" to="/">Dashboard</NuxtLink><NuxtLink class="nav" to="/racks">Visual Racks</NuxtLink><NuxtLink class="nav" to="/devices">Device Inventory</NuxtLink><NuxtLink class="nav" to="/connections">Patch Connections</NuxtLink><NuxtLink v-if="user?.role === 'admin'" class="nav" to="/admin/users">Administration</NuxtLink><div class="muted" style="margin-top:35px">{{user?.display_name}} · {{user?.role}}</div><button style="margin-top:10px" @click="logout">Sign out</button></aside><main class="main"><slot /></main></div></template><script setup lang="ts">const user=useAuth();async function logout(){await $fetch('/api/auth/logout',{method:'POST'});user.value=null;await navigateTo('/login')}</script>
